     "id": "CPP-4.1-R1-05",
     "ponto": "DBA26-CPP-4.1",
     "tema": "Decadência na violência doméstica",
     "assertiva": "Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, o prazo decadencial para a queixa ou a representação é o mesmo de seis meses dos demais crimes.",
