     "ponto": "DBA26-CPP-6",
     "tema": "Termo inicial dos prazos",
     "assertiva": "No processo penal, contam-se os prazos da data da juntada aos autos do mandado ou da carta precatória, e não da intimação.",
     "gabarito": "E",
