     "ponto": "DBA26-CPP-8.6",
     "tema": "Ajuste do valor",
     "assertiva": "Conforme a situação econômica do preso, a fiança poderá ser dispensada, reduzida até o máximo de 2/3 ou aumentada em até 1.000 vezes.",
     "gabarito": "C",
