     "ponto": "DBA26-CPP-4.2",
     "tema": "Condições abusivas",
     "assertiva": "Se o juiz considerar inadequadas, insuficientes ou abusivas as condições do ANPP, poderá ele mesmo reformulá-las e homologar o acordo com as novas condições.",
