     "assertiva": "O uso de algemas é lícito em casos de resistência, de fundado receio de fuga ou de perigo à integridade física própria ou alheia, justificada a excepcionalidade por escrito.",
     "gabarito": "C",
     "comentario": {
      "resumo": "**SV 11**. E o art. 292, par. ún., do CPP veda algemas em mulheres durante o trabalho de parto e o puerpério imediato.",
      "lei": [
       {
        "lei": "CPP",
        "art": "292",
        "par": "",
        "inc": "",
        "rotulo": "CPP, art. 292, par. ún.",
        "texto": "É vedado o uso de algemas em mulheres grávidas durante os atos médico-hospitalares preparatórios para a realização do parto"
       }
      ],
      "juris": [
       {
        "tribunal": "STF",
        "fonte": "Súmula Vinculante 11 (publicada no DJe de 22/08/2008)",
        "data": "22/08/2008",
        "texto": "Só é lícito o uso de algemas em casos de resistência, fundado receio de fuga ou perigo à integridade física própria ou alheia, justificada a excepcionalidade por escrito, sob pena de responsabilidade e de nulidade da prisão ou do ato."
       }
      ],
      "palavras_chave": [
       "SV 11",
       "algemas"
      ]
     }
